 $('plan-flight').onclick=()=>{if(!start||!end){message('请先选择起点和终点，或载入示例。');return;}emit('preview');invalidate('正在后台搜索三维航线…');tool('inspect');$('plan-flight').disabled=true;worker=new Worker('./planner-worker.js',{type:'module'});const current=worker;worker.onmessage=e=>{if(worker!==current)return;worker.terminate();worker=null;$('plan-flight').disabled=false;if(e.data.error){message(e.data.error);return;}route=e.data.route;elapsed=0;buildRoute();for(const id of ['play-flight','restart-flight','flight-progress','export-flight'])$(id).disabled=false;message(`规划完成 · ${route.cell} m 网格 / ${route.levels.length} 个高度层 · ${(route.computeMs/1000).toFixed(2)} 秒`);$('flight-metrics').innerHTML=`<div><b>${(route.distance/1000).toFixed(2)} km</b><span>三维航程</span></div><div><b>${(route.seconds/60).toFixed(1)} min</b><span>模拟用时</span></div><div><b>${Math.max(...route.points.map(p=>p.y)).toFixed(0)} m</b><span>最高高度</span></div><div><b>${route.climb.toFixed(0)} m</b><span>累计爬升</span></div>`;};worker.onerror=()=>{invalidate('规划模块加载失败，请刷新页面后重试。')};worker.postMessage({buildings,zones,start,end,width:data.width,depth:data.depth,params:params()});};
 $('demo-flight').onclick=()=>{const index=obstacleIndex(buildings,zones,params().clearance,params().vertical);const find=(target)=>{for(let radius=0;radius<500;radius+=25)for(let a=0;a<Math.PI*2;a+=Math.PI/8){const p={x:target+Math.cos(a)*radius,y:0,z:Math.sin(a)*radius};if(Math.abs(p.x)>data.width/2-50||Math.abs(p.z)>data.depth/2-50)continue;if(index.clear(p,{...p,y:params().ceiling}))return p;}return null;};start=find(-data.width*.27);end=find(data.width*.27);invalidate(start&&end?'示例起终点已放置。点击“计算三维航线”。':'未找到示例空地，请手动选点。');markPoints();tool('inspect');};
 const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
 function updateFlight(){if(!route)return;const p=positionAt(route,elapsed);drone.position.set(p.x,p.y,p.z);const next=positionAt(route,Math.min(route.seconds,elapsed+.5));if(Math.hypot(next.x-p.x,next.z-p.z)>.01)drone.rotation.y=Math.atan2(next.x-p.x,next.z-p.z);shadow.position.set(p.x,1,p.z);lineDown.geometry.setFromPoints([new THREE.Vector3(p.x,1,p.z),new THREE.Vector3(p.x,p.y,p.z)]);$('flight-time').textContent=clock(elapsed)+' / '+clock(route.seconds);$('flight-progress').value=Math.round(1000*elapsed/route.seconds);let gap=Infinity;for(const b of queryIndex.obstacles){if(b.id.startsWith('ZONE-'))continue;const c=Math.cos(b.angle||0),s=Math.sin(b.angle||0),x=c*(p.x-b.x)-s*(p.z-b.z),z=s*(p.x-b.x)+c*(p.z-b.z);gap=Math.min(gap,Math.hypot(Math.max(Math.abs(x)-b.width/2,0),Math.max(Math.abs(z)-b.depth/2,0),Math.max(b.bottom-p.y,p.y-b.top,0)));}$('flight-position').textContent=`高度 ${p.y.toFixed(1)} m · 东 ${p.x.toFixed(0)} / 北 ${(-p.z).toFixed(0)} m · 建筑几何净距 ${Number.isFinite(gap)?gap.toFixed(1):'—'} m`;if(follow){const target=new THREE.Vector3(p.x,p.y*factor,p.z);api.controls.target.copy(target);api.camera.position.copy(target).add(new THREE.Vector3(240,200,240));api.camera.lookAt(target);}drawProfile();}
 function drawProfile(){const r=profile.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);profile.width=Math.max(1,r.width*d);profile.height=150*d;ctx.setTransform(d,0,0,d,0,0);const w=r.width,h=150;ctx.clearRect(0,0,w,h);if(!route)return;const max=Math.max(params().ceiling,...profileSamples.map(p=>p.h))*1.15,x=i=>40+(w-60)*i/240,y=v=>125-v/max*105;ctx.font='10px sans-serif';ctx.fillStyle='#819085';for(let i=0;i<=3;i++){const value=max*i/3;ctx.fillText(value.toFixed(0),2,y(value));ctx.strokeStyle='#e4e9e2';ctx.beginPath();ctx.moveTo(38,y(value));ctx.lineTo(w-15,y(value));ctx.stroke();}profileSamples.forEach((p,i)=>{ctx.fillStyle='#d3ddd1';ctx.fillRect(x(i),y(p.h),(w-60)/240+1,125-y(p.h));ctx.fillStyle='#d8867040';p.blocked.forEach(([a,b])=>ctx.fillRect(x(i),y(Math.min(b,max)),(w-60)/240+1,y(a)-y(Math.min(b,max))));});ctx.beginPath();profileSamples.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.y)):ctx.moveTo(x(i),y(p.y)));ctx.strokeStyle='#177e66';ctx.lineWidth=2;ctx.stroke();const i=elapsed/route.seconds*240;ctx.strokeStyle='#d38b59';ctx.beginPath();ctx.moveTo(x(i),10);ctx.lineTo(x(i),128);ctx.stroke();ctx.fillStyle='#819085';ctx.fillText('0:00',40,145);ctx.fillText(clock(route.seconds),w-55,145);}
 $('play-flight').onclick=()=>{if(!route)return;emit('preview');if(elapsed>=route.seconds)elapsed=0;playing=!playing;last=0;$('play-flight').textContent=playing?'❚❚ 暂停':'▶ 播放';};$('restart-flight').onclick=()=>{emit('preview');playing=false;elapsed=0;$('play-flight').textContent='▶ 播放';updateFlight();};$('flight-progress').oninput=e=>{if(!route)return;emit('preview');playing=false;$('play-flight').textContent='▶ 播放';elapsed=route.seconds*Number(e.target.value)/1000;updateFlight();};profile.onclick=e=>{if(!route)return;emit('preview');const r=profile.getBoundingClientRect();elapsed=Math.max(0,Math.min(1,(e.clientX-r.left-40)/(r.width-60)))*route.seconds;playing=false;$('play-flight').textContent='▶ 播放';updateFlight();};$('follow-flight').onchange=e=>{follow=e.target.checked;if(route)updateFlight()};
 $('export-flight').onclick=()=>{if(!route)return;const originals=new Map(original.map(b=>[b.id,JSON.stringify(b)])),currentIds=new Set(buildings.map(b=>b.id));const content={version:1,map:{width:data.width,depth:data.depth,source:data.source},params:params(),start,end,zones,buildingEdits:buildings.filter(b=>originals.get(b.id)!==JSON.stringify(b)),removedBuildingIds:original.filter(o=>!currentIds.has(o.id)).map(b=>b.id),route};const url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tianjin-flight-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
