 return {subscribe(fn){listeners.add(fn);},setPreviewVisible(visible){overlay.visible=markers.visible=visible;},getParams:params,getScene(){return data?{width:data.width,depth:data.depth,buildings,zones}:null;},getSceneRecord(){const originals=new Map(original.map(b=>[b.id,JSON.stringify(b)])),ids=new Set(buildings.map(b=>b.id));return {width:data.width,depth:data.depth,source:data.source,zones,buildingEdits:buildings.filter(b=>originals.get(b.id)!==JSON.stringify(b)),removedBuildingIds:original.filter(b=>!ids.has(b.id)).map(b=>b.id)};},getDraft(){return route?structuredClone({start,end,params:params(),route}):null;},syncEnabled(){for(const id of ["play-flight","restart-flight","flight-progress","export-flight"])document.getElementById(id).disabled=!route;document.getElementById("plan-flight").disabled=!!worker;},handleClick,handleHover,selectBuilding,setScene(next){emit('scene');data=next;original=structuredClone(next.buildings);buildings=next.buildings;zones=[];start=end=null;selected=-1;invalidate('选择起终点后开始规划。');selectBuilding(-1);markPoints();showZones();tool('inspect');},setFactor(v){factor=v;overlay.scale.y=markers.scale.y=airspace.scale.y=v;if(route)updateFlight();},tick(now){sizeCornerLabels();if(playing&&route){if(last)elapsed=Math.min(route.seconds,elapsed+(now-last)/1000*Number($('flight-rate').value));last=now;updateFlight();if(elapsed>=route.seconds){playing=false;$('play-flight').textContent='▶ 播放';}}else last=0;},pause(){playing=false;last=0;$('play-flight').textContent='▶ 播放';}};
